MASK64 = (1 << 64) - 1


def write_new(path: Path, value: object) -> None:
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def sha_text(text: str) -> str:
    return hashlib.sha256(text.encode()).hexdigest()


def source_hashes() -> dict[str, str]:
    files = sorted((HERE / 'src').rglob('*.java')) + [Path(__file__).resolve()]
    return {str(p.relative_to(HERE)): identity.sha(p) for p in files}


def java_string_hash(text: str) -> int:
    result = 0
    for char in text:
        result = (result * 31 + ord(char)) & 0xffffffff
    return result if result < (1 << 31) else result - (1 << 32)


def mix(value: int, text: str) -> int:
    return ((value ^ java_string_hash(text)) * 0x100000001b3) & MASK64


def expected(roots: int, left: int, right: int, width: int) -> dict:
    ns = 'urn:shared-selection:'
    names = ['s', 'a'] + [f'l{i}' for i in range(width)] + [f'r{i}' for i in range(width)]
    query = f'PREFIX ex: <{ns}>\nSELECT' + ''.join(' ?' + n for n in names) + ' WHERE {\n  ?s ex:outer ?a .\n'
    for side, var in [('left', 'l'), ('right', 'r')]:
        query += f'  OPTIONAL {{ ?a ex:{side} ?{var}0 .'
        for col in range(1, width):
            query += f' ?{var}{col-1} ex:{side}{col} ?{var}{col} .'
        query += ' }\n'
    query += '}\n'
    checksum = 0
    root_hash = mix(0xcbf29ce484222325, ns + 'root')
    graph = []
    for a in range(roots):
        graph.append(f'<{ns}root> <{ns}outer> <{ns}a{a}> .\n')
        for side, count in [('left', left), ('right', right)]:
            for i in range(a * count, (a + 1) * count):
                graph.append(f'<{ns}a{a}> <{ns}{side}> <{ns}{side}0_{i}> .\n')
                for col in range(1, width):
                    graph.append(f'<{ns}{side}{col-1}_{i}> <{ns}{side}{col}> <{ns}{side}{col}_{i}> .\n')
        outer_hash = mix(root_hash, ns + f'a{a}')
        for l in range(left):
            left_hash = outer_hash
            for col in range(width):
                left_hash = mix(left_hash, ns + f'left{col}_{a * left + l}')
            for r in range(right):
                row_hash = left_hash
                for col in range(width):
                    row_hash = mix(row_hash, ns + f'right{col}_{a * right + r}')
                checksum = (checksum + row_hash) & MASK64
    signed = checksum if checksum < (1 << 63) else checksum - (1 << 64)
    return {'roots': roots, 'left': left, 'right': right, 'tupleWidth': width,
            'rows': roots * left * right, 'width': len(names), 'names': names,
            'checksum': str(signed), 'statements': roots * (1 + width * (left + right)),
            'query': query, 'querySha256': sha_text(query),
            'insertionSha256': sha_text(''.join(graph)),
            'canonicalGraphSha256': sha_text(''.join(sorted(graph))),
            'oracle': 'Exact all-IRI tuple membership, parent association, unique dense row-key bitset, full count, and independent checksum.'}


def prepare() -> None:
    cp, manifest = identity.original_identity()
    plan = {
        'format': 1, 'status': 'prospective; no experiment JVM started by preparation',
        'name': 'Shared coherent OPTIONAL-tail source rows under normal AUTO',
        'sourceHashes': source_hashes(), 'frozenProductionSource': identity.ORIGINAL_SOURCE,
        'baseClasspath': cp, 'baseClasspathManifest': manifest,
        'java': str(JAVA), 'jvmArguments': ['-Xms1024m', '-Xmx1024m', '-XX:+UseG1GC'],
        'fixture': expected(64, 128, 128, 2),
        'strategy': 'normal AUTO; native and direct adjacency PREFER enabled through repository config; no strategy or tier overrides',
        'pilot': {'arms': ['off', 'dense', 'rows'], 'warmup': 3, 'iterations': 1,
                  'purpose': 'Participation/route qualification only; no latency winner selected from this pilot'},
        'comparison': {'orders': [['off', 'dense', 'rows'], ['dense', 'rows', 'off'], ['rows', 'off', 'dense'],
                                   ['rows', 'dense', 'off'], ['off', 'rows', 'dense'], ['dense', 'off', 'rows']],
                       'warmup': 8, 'iterations': 5,
                       'statistic': 'All five measurements per fork median; within-round ratios; median and complete range of six paired ratios'},
        'qualification': 'Every mode exact bag/checksum/zero endpoint ledger; absolute outer-root HOSTED_GENERIC=0; measured normal compiled IR, matching selection signatures; ROWS one owner, every output row encoded, no refusals, groups/columns < 1',
        'failurePolicy': 'Preserve failures and all rows; stop. No replacement forks, favorable tail selection, performance-driven extensions, or forced-route rescue.',
        'quietPeriod': 'Serial fresh JVMs; no overlapping builds, tests, profiling, compression, or other benchmarks.',
        'measurementScope': 'New fixture with exact oracle overhead, not numerically pooled with prior fanout experiments. Oracle bitset and lexical scratch are preallocated outside query timing; every result IRI is consumed and checked inside it.',
        'hypothesis': 'Coherent multi-column tails can make ROWS groups/columns < 1 and reduce transport work; this must be observed before timing conclusions.',
    }
    write_new(PLAN, plan)
    print(json.dumps({'protocol': str(PLAN), 'expected': plan['fixture'], 'javaExecuted': False}, indent=2))


def read_plan() -> dict:
    plan = json.loads(PLAN.read_text())
    assert plan['sourceHashes'] == source_hashes(), 'Harness sources changed since prospective protocol'
    assert plan['java'] == str(JAVA)
    cp, manifest = identity.original_identity()
    assert manifest == plan['baseClasspathManifest'] and cp == plan['baseClasspath']
    return plan


def compile_harness() -> None:
    plan = read_plan()
    classes = HERE / 'classes'
    classes.mkdir(exist_ok=False)
    command = [str(JAVA.with_name('javac')), '--release', '25', '-cp', plan['baseClasspath'], '-d', str(classes)]
    command += [str(p) for p in sorted((HERE / 'src').rglob('*.java'))]
    write_new(HERE / 'compile-command.json', {'argv': command, 'cwd': str(ROOT)})
    with (HERE / 'compile.log').open('x') as output:
        done = subprocess.run(command, cwd=ROOT, stdout=output, stderr=subprocess.STDOUT)
    assert done.returncode == 0, 'javac failed; preserve compile.log'
    cp = str(classes) + os.pathsep + plan['baseClasspath']
    manifest = identity.classpath_manifest(cp)
    assert manifest[1:] == plan['baseClasspathManifest']
    own_files = set(identity.tree_files(classes))
    for item in manifest[1:]:
        if item['kind'] == 'tree':
            assert not own_files.intersection(identity.tree_files(item['path'])), 'Overlay shadows existing runtime class'
    write_new(RUNTIME, {'classpath': cp, 'manifest': manifest, 'protocolSha256': identity.sha(PLAN),
                        'sourceHashes': plan['sourceHashes'], 'productionUnchanged': True})
    print('Compiled separate harness overlay; original 127 runtime entries unchanged.')


def read_runtime(plan: dict) -> dict:
    runtime = json.loads(RUNTIME.read_text())
    assert runtime['protocolSha256'] == identity.sha(PLAN) and runtime['sourceHashes'] == plan['sourceHashes']
    assert identity.classpath_manifest(runtime['classpath']) == runtime['manifest']
    assert runtime['manifest'][1:] == plan['baseClasspathManifest']
    return runtime


def validate_fixture() -> None:
    plan = read_plan()
    runtime = read_runtime(plan)
    command = [str(JAVA), '-ea', '-cp', runtime['classpath'],
               'org.eclipse.rdf4j.sail.lmdb.benchmark.SharedSelectionFixtureCheck']
    done = subprocess.run(command, cwd=ROOT, text=True, capture_output=True)
    write_new(HERE / 'fixture-validation.json', {'argv': command, 'returncode': done.returncode,
                                               'stdout': done.stdout, 'stderr': done.stderr,
                                               'runtimeSha256': identity.sha(RUNTIME)})
    assert done.returncode == 0, 'Fixture validation failed'
    print(done.stdout.strip())


def observations(folder: Path, plan: dict, arm: str, warmup: int, iterations: int) -> dict:
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
    assert records[0]['type'] == 'metadata' and len(records) == 1 + warmup + iterations
    metadata = records[0]
    expected_fixture = plan['fixture']
    for key, expected_key in [('expectedRows', 'rows'), ('expectedChecksum', 'checksum'), ('statements', 'statements'),
                              ('canonicalGraphSha256', 'canonicalGraphSha256'), ('fixtureInsertionSha256', 'insertionSha256'),
                              ('querySha256', 'querySha256')]:
        assert metadata[key] == expected_fixture[expected_key], (key, metadata[key], expected_fixture[expected_key])
    assert metadata['nativeEvaluation'] and metadata['directAdjacency']
    assert metadata['systemProperties'].get('rdf4j.lmdb.resultCoordinateTransport') == arm
    measured = []
    for index, sample in enumerate(records[1:]):
        assert sample['type'] == 'sample' and sample['valid'] and sample['exactBagValid']
        assert sample['rows'] == expected_fixture['rows'] and sample['checksum'] == expected_fixture['checksum']
        assert sample['ledgerBeforeBytes'] == 0 and sample['ledgerAfterBytes'] == 0
        assert sample['iteration'] == index - warmup
        assert sample['stage'] == ('warmup' if index < warmup else 'measurement')
        if index >= warmup:
            measured.append(sample)
    audit = json.loads((folder / 'root-host-audit.json').read_text())
    assert audit['harnessReturned']
    native_root = audit['hostedGenericTotal'] == 0 and audit['semanticNativeCompilesTotal'] == warmup + iterations
    compiled_ir = all(s['counters']['compiledBinds'] > 0 and s['counters']['interpretedBinds'] == 0
                      and s['auto'] is True and any(r['point'] == 'ROW' and r['strategy'] == 'irKernel'
                      and r['mode'] == 'normal' for r in s['successfulSelections']) for s in measured)
    sharing = None
    if arm == 'rows':
        sharing = []
        for sample in measured:
            d = sample['counters']['coordinateAdmissions']
            sharing.append({'rows': d['rowSelectionRows'], 'groups': d['rowSelectionGroups'],
                            'columns': d['rowSelectionColumns'],
                            'groupsPerColumn': None if not d['rowSelectionColumns'] else d['rowSelectionGroups'] / d['rowSelectionColumns'],
                            'qualified': d['rowSelectionOwners'] == 1 and d['rowSelectionRows'] == expected_fixture['rows']
                            and 0 < d['rowSelectionGroups'] < d['rowSelectionColumns']
                            and d['rowSelectionInvariantRefused'] == 0 and d['initialAdmissionRefused'] == 0
                            and d['growthAdmissionRefused'] == 0})
    fields = ['totalNs', 'allThreadAllocatedBytes', 'prepareNs', 'evaluateNs', 'consumeNs', 'ledgerPeakBytes']
    return {'arm': arm, 'allResultsExact': True, 'nativeOuterRoot': native_root, 'compiledIr': compiled_ir,
            'rootAudit': audit, 'sharing': sharing,
            'selectionSignatures': [s['successfulSelections'] for s in measured],
            'medians': {k: statistics.median(s[k] for s in measured) for k in fields},
            'records': len(records)-1}


def run_arm(folder: Path, plan: dict, runtime: dict, arm: str, warmup: int, iterations: int) -> dict:
    folder.mkdir(exist_ok=False)
    f = plan['fixture']
    command = [str(JAVA)] + plan['jvmArguments'] + [f'-Drdf4j.lmdb.resultCoordinateTransport={arm}',
               '-cp', runtime['classpath'], 'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedSharedSelectionLauncher',
               f'--arm={arm}', f"--source={plan['frozenProductionSource']}", f"--roots={f['roots']}",
               f"--left={f['left']}", f"--right={f['right']}", f"--tuple-width={f['tupleWidth']}",
               f'--warmup={warmup}', f'--iterations={iterations}', '--consumption=full',
               f'--store={folder / "store"}', f'--output={folder / "samples.jsonl"}']
    write_new(folder / 'command.json', {'argv': command, 'cwd': str(ROOT)})
    with (folder / 'console.log').open('x') as log:
        done = subprocess.run(command, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=300)
    assert done.returncode == 0, f'Experiment failed: {folder}; keep every record and do not replace it'
    result = observations(folder, plan, arm, warmup, iterations)
    write_new(folder / 'validation.json', result)
    print(json.dumps({'folder': str(folder), 'arm': arm, 'nativeOuterRoot': result['nativeOuterRoot'],
                      'compiledIr': result['compiledIr'], 'sharing': result['sharing']}, sort_keys=True), flush=True)
    return result


def pilot() -> None:
    plan = read_plan()
    runtime = read_runtime(plan)
    validation = json.loads((HERE / 'fixture-validation.json').read_text())
    assert validation['returncode'] == 0 and validation['runtimeSha256'] == identity.sha(RUNTIME)
    folder = HERE / 'pilot'
    folder.mkdir(exist_ok=False)
    settings = plan['pilot']
    results = [run_arm(folder / arm, plan, runtime, arm, settings['warmup'], settings['iterations'])
               for arm in settings['arms']]
    signature = results[0]['selectionSignatures'][0]
    matching = all(all(s == signature for s in r['selectionSignatures']) for r in results)
    qualified = matching and all(r['nativeOuterRoot'] and r['compiledIr'] for r in results)
    qualified = qualified and all(s['qualified'] for s in results[-1]['sharing'])
    read_runtime(plan)
    write_new(folder / 'qualification.json', {'qualifiedForTiming': qualified, 'matchingRoutes': matching,
              'results': results, 'interpretation': 'Participation/route pilot only; no performance conclusion.'})
    print('QUALIFIED_FOR_TIMING=' + str(qualified))


def compare() -> None:
    plan = read_plan()
    runtime = read_runtime(plan)
    assert json.loads((HERE / 'pilot/qualification.json').read_text())['qualifiedForTiming'], 'Sharing/route pilot did not qualify'
    folder = HERE / 'comparison'
    folder.mkdir(exist_ok=False)
    all_rounds = []
    settings = plan['comparison']
    for number, order in enumerate(settings['orders']):
        group = {}
        for position, arm in enumerate(order):
            group[arm] = run_arm(folder / f'round{number:02d}-position{position}-{arm}', plan, runtime,
                                  arm, settings['warmup'], settings['iterations'])
        all_rounds.append(group)
    read_runtime(plan)
    pairs = {}
    for target, base in [('dense', 'off'), ('rows', 'off'), ('rows', 'dense')]:
        metric = {}
        for name in ('totalNs', 'allThreadAllocatedBytes', 'ledgerPeakBytes', 'prepareNs'):
            values = [r[target]['medians'][name] / r[base]['medians'][name] for r in all_rounds]
            metric[name] = {'pairs': values, 'median': statistics.median(values), 'minimum': min(values), 'maximum': max(values)}
        pairs[target + '/' + base] = metric
    signature = all_rounds[0]['off']['selectionSignatures'][0]
    qualified = all(r['nativeOuterRoot'] and r['compiledIr']
                    and all(s == signature for s in r['selectionSignatures'])
                    and (r['sharing'] is None or all(s['qualified'] for s in r['sharing']))
                    for group in all_rounds for r in group.values())
    write_new(folder / 'summary.json', {'qualifiedForRepresentationComparison': qualified,
              'freshJvms': 18, 'queries': 234, 'pairs': pairs, 'rounds': all_rounds,
              'statistics': settings['statistic'], 'protocolSha256': identity.sha(PLAN),
              'noSamplesReplacedOrExcluded': True})
    print(json.dumps({'qualifiedForRepresentationComparison': qualified, 'pairs': pairs}, indent=2))


